curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        if 'maya' in user.get('real_name','').lower() or 'maya' in user.get('username','').lower():
            print(json.dumps(user, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&channel=D_MAYA" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        print(f\"TS: {msg['ts']} | User: {msg['user']} | Text: {msg.get('text','')}\"  )
else:
    print(json.dumps(data, indent=2))
"
